[["capacitor", "Capacitor", "Stores charge like a small tank. Electrolytics (cans) have a + and − side; ceramics (beads) don't. 104 means 100 nF.", "E18"], ["diode", "Diode", "Lets current through one way only. The band marks the cathode (−) end.", "E18"], ["transistor", "Transistor", "A small current into the base switches a bigger one between collector and emitter. NPN switches the − side, PNP the + side.", "E18"], ["timeconst", "Time constant (RC)", "R × C in seconds: how long a capacitor takes to reach 63% through a resistor. Five of them and it's full.", "E19"], ["flyback", "Flyback diode", "A diode across a coil (relay or motor) that gives its switch-off spike a safe path instead of the transistor.", "E20"], ["micropython", "MicroPython", "Python made small enough to run on a microcontroller like the Pico 2.", "E22"], ["uf2", "UF2", "A firmware file you drag onto a board's USB drive to install it, as with MicroPython on the Pico.", "E22"], ["perfboard", "Perfboard", "Board full of separate plated holes. You solder parts in and join them with wire: a breadboard circuit made permanent.", "E24"], ["protocol", "Protocol", "An agreed message format two programs use to talk, like the Pi's AUR|...|... lines to the UNO.", "E17"], ["spi", "SPI", "A fast wired link for screens and chips: a clock wire, a data wire and a chip-select that picks which device listens.", "E17"], ["debounce", "Debounce", "Ignoring the few milliseconds of flicker when a button's contacts bounce, so one press counts once.", "E17"], ["buzzer", "Active vs passive buzzer", "An active buzzer beeps on its own when powered. A passive buzzer is a tiny speaker that plays the frequency you send it with tone().", "E17"], ["millis", "millis()", "Milliseconds since the board powered on. Checking it instead of using delay() lets a sketch do several things at once.", "E17"], ["oled", "OLED", "A screen where every pixel makes its own light: deep blacks, no backlight, but pixels can wear unevenly.", "E17"], ["burnin", "Burn-in", "An OLED ghost image left where the same thing was shown for hours. Avoid it by dimming, sleeping and shifting the picture.", "E17"], ["asahi", "Asahi Linux", "The project that makes Linux run on Apple-chip Macs.", "B2"], ["fedora", "Fedora", "The Linux Primus (MFOB) runs. Same commands as the Pi's, different package manager.", "B2"], ["dnf", "dnf", "Fedora's package manager; the equivalent of apt on the Pi.", "B3"], ["selinux", "SELinux", "A security guard in Fedora that labels files and limits what each service can touch.", "B3"], ["cockpit", "Cockpit", "A web dashboard for managing a Linux machine from any browser.", "B5"], ["systemd", "systemd service", "A program the system starts, watches and restarts. Managed with systemctl.", "B5"], ["mount", "Mount", "Attaching a drive to a folder so its files appear there, like /srv/vault.", "B6"], ["fstab", "fstab", "The file listing which drives mount where at boot: /etc/fstab.", "B6"], ["tailscale", "Tailscale", "A private network between your own devices that works from anywhere.", "B7"], ["docker", "Docker", "Runs apps in self-contained boxes (containers) with everything they need.", "B8"], ["immich", "Immich", "A private, self-hosted Google Photos.", "B8"], ["rsync", "rsync", "Copies files, sending only what changed. The workhorse of backups.", "B9"], ["samba", "Samba", "Shares folders as network drives that Windows, Mac and Android can open.", "B10"], ["venv", "venv", "A private Python environment for one project, so its libraries don't clash with the system's.", "L12"], ["gesture", "Gesture", "A movement or hand shape the software recognizes and turns into a command.", "L13"], ["i2s", "I2S", "A way of sending digital audio between chips, used by the deck's speaker amp.", "E11"], ["imu", "IMU", "Inertial measurement unit: a motion sensor measuring acceleration and rotation.", "E12"], ["i2c", "I2C", "A two-wire connection (SDA and SCL) that lets several small devices share the same pins. Each device answers at its own address, like 0x3C.", "E21"], ["ble", "BLE", "Bluetooth Low Energy: short-range, low-power wireless for small devices.", "E14"], ["lipo", "LiPo", "Lithium-polymer pouch battery. Light and flat, and must never be punctured or crushed.", "E15"], ["callsign", "Callsigns", "MFOB (Murph FOB) is the whole home setup. Its stations take Latin ordinals: the MacBook server is Primus Station (hostname primus-station), the deck is Secundus Station (secundus-station), the next box Tertius Station. On air: \"Primus Station, this is Secundus Station.\"", "B3"]].forEach(([id, t, d, from]) => TERMS.push({ id, t, d, from }));
